import React, { useEffect, useState, useRef } from 'react';
import ReactECharts from 'echarts-for-react';
import { Card, Radio, Slider, Space, Switch, Spin } from 'antd';
import { getWeatherStations } from '../../services/mockData';
import { WeatherStation, WeatherType } from '../../types';
import * as echarts from 'echarts';
import axios from 'axios';

const Visualization2D: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [stations, setStations] = useState<WeatherStation[]>([]);
  const [dataType, setDataType] = useState<WeatherType>('temperature');
  const [showScatter, setShowScatter] = useState(true);
  const [showHeatmap, setShowHeatmap] = useState(true);
  const [geoJson, setGeoJson] = useState<any>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const data = await getWeatherStations();
        setStations(data);
        
        // Load Jinhua GeoJSON (using a placeholder or online source if available)
        // For demo, we might need to rely on a standard map or fetch a specific one.
        // Let's try to fetch a GeoJSON for Zhejiang or Jinhua.
        // If this fails, ECharts has world/China maps often included or we can use coordinate system.
        // For now, let's use a coordinate system on a blank canvas or standard map if possible.
        // To make it work reliably without external dependencies, we will use 'bmap' (Baidu Map) or 'amap' extension if available,
        // but standard ECharts geo is best.
        // Let's assume we can fetch a simplified GeoJSON for Jinhua.
        
        // Fallback: simpler visualization without complex borders if fetch fails
        // Or better: use a public URL for Jinhua GeoJSON.
        const response = await axios.get('https://geo.datav.aliyun.com/areas_v3/bound/330700_full.json');
        echarts.registerMap('jinhua', response.data);
        setGeoJson(response.data);
      } catch (error) {
        console.error('Failed to load data', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const getOption = () => {
    if (!stations.length) return {};

    const data = stations.map(s => {
      let value = 0;
      switch (dataType) {
        case 'temperature': value = s.data.temperature || 0; break;
        case 'precipitation': value = s.data.precipitation || 0; break;
        case 'wind': value = s.data.windSpeed || 0; break;
        case 'humidity': value = s.data.humidity || 0; break;
      }
      return {
        name: s.name,
        value: [s.longitude, s.latitude, value]
      };
    });

    return {
      title: {
        text: `金华市气象要素展示 - ${
          dataType === 'temperature' ? '温度' :
          dataType === 'precipitation' ? '降水' :
          dataType === 'wind' ? '风速' : '湿度'
        }`,
        left: 'center'
      },
      tooltip: {
        trigger: 'item',
        formatter: (params: any) => {
          return `${params.name}<br/>${dataType}: ${params.value[2].toFixed(1)}`;
        }
      },
      visualMap: {
        min: dataType === 'precipitation' ? 0 : 0,
        max: dataType === 'temperature' ? 40 : dataType === 'precipitation' ? 100 : 20,
        calculable: true,
        inRange: {
          color: dataType === 'temperature' 
            ? ['#313695', '#4575b4', '#74add1', '#abd9e9', '#e0f3f8', '#ffffbf', '#fee090', '#fdae61', '#f46d43', '#d73027', '#a50026']
            : ['#e0f3f8', '#74add1', '#313695']
        },
        text: ['High', 'Low'],
        left: 'right',
        bottom: '20'
      },
      geo: {
        map: 'jinhua',
        roam: true,
        label: {
          show: true,
          color: '#fff'
        },
        itemStyle: {
          areaColor: '#323c48',
          borderColor: '#111'
        },
        emphasis: {
          itemStyle: {
            areaColor: '#2a333d'
          }
        }
      },
      series: [
        showScatter && {
          name: '站点',
          type: 'scatter',
          coordinateSystem: 'geo',
          data: data,
          symbolSize: 10,
          itemStyle: {
            color: '#fff'
          }
        },
        showHeatmap && {
          name: '热力图',
          type: 'heatmap',
          coordinateSystem: 'geo',
          data: data,
          pointSize: 20,
          blurSize: 20
        }
      ].filter(Boolean)
    };
  };

  return (
    <div className="h-full flex flex-col">
      <div className="mb-4 flex justify-between items-center bg-white p-4 rounded shadow-sm">
        <Space size="large">
          <div>
            <span className="mr-2 font-bold">要素类型:</span>
            <Radio.Group value={dataType} onChange={e => setDataType(e.target.value)}>
              <Radio.Button value="temperature">温度</Radio.Button>
              <Radio.Button value="precipitation">降水</Radio.Button>
              <Radio.Button value="wind">风速</Radio.Button>
              <Radio.Button value="humidity">湿度</Radio.Button>
            </Radio.Group>
          </div>
          <div>
            <span className="mr-2">显示散点:</span>
            <Switch checked={showScatter} onChange={setShowScatter} />
          </div>
          <div>
            <span className="mr-2">显示热力:</span>
            <Switch checked={showHeatmap} onChange={setShowHeatmap} />
          </div>
        </Space>
      </div>

      <div className="flex-1 bg-white rounded shadow-sm p-4 relative">
        {loading ? (
          <div className="absolute inset-0 flex items-center justify-center">
            <Spin size="large" tip="加载地图数据中..." />
          </div>
        ) : (
          <ReactECharts 
            option={getOption()} 
            style={{ height: '100%', width: '100%' }}
            notMerge={true}
          />
        )}
      </div>
    </div>
  );
};

export default Visualization2D;
